* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--surface);
  color: var(--text);
  padding: 0.75rem 1rem;
  border: 2px solid var(--focus);
  border-radius: 6px;
  z-index: 100;
}
.skip-link:focus {
  left: 1rem;
  top: 1rem;
}

.page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

.card {
  width: 100%;
  max-width: 32rem;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 2rem;
  border: 1px solid var(--border);
}

.card__header { margin-bottom: 1.5rem; }

h1 {
  font-size: 1.625rem;
  margin: 0 0 0.5rem;
  letter-spacing: -0.01em;
}

.card__lede {
  margin: 0 0 0.75rem;
  color: var(--muted);
}

.card__legend {
  margin: 0;
  font-size: 0.875rem;
  color: var(--muted);
}

.req { color: var(--accent); margin-left: 0.15rem; }
.optional { color: var(--muted); font-weight: 400; font-size: 0.9em; margin-left: 0.25rem; }

.contact-form { display: flex; flex-direction: column; gap: 1.25rem; }

.form-field { display: flex; flex-direction: column; gap: 0.4rem; }

.form-field label {
  font-weight: 600;
  font-size: 0.95rem;
}

.form-field input {
  font: inherit;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  padding: 0.65rem 0.8rem;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

.form-field input::placeholder { color: var(--muted); }

.form-field input:hover { border-color: var(--text); }

.form-field input:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--focus);
}

.form-field__help {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.form-actions { margin-top: 0.5rem; }

.btn {
  font: inherit;
  font-weight: 600;
  border-radius: 8px;
  padding: 0.7rem 1.25rem;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 120ms ease, border-color 120ms ease;
}

.btn--primary {
  background: var(--accent);
  color: var(--accent-contrast);
  width: 100%;
}

.btn--primary:hover { background: var(--accent-hover); }

.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.form-status {
  margin: 0;
  font-size: 0.95rem;
  min-height: 1.25rem;
  color: var(--muted);
}
.form-status.is-success { color: #0f6b3a; }
@media (prefers-color-scheme: dark) {
  .form-status.is-success { color: #6ee7a8; }
}

@media (forced-colors: active) {
  .card { border: 1px solid CanvasText; }
  .form-field input { border: 1px solid CanvasText; }
  .form-field input:focus-visible { outline: 2px solid Highlight; }
  .btn--primary { border: 1px solid ButtonText; }
}
