  if (!form) return;

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    status.classList.remove('is-success');
    status.textContent = '';

    const firstInvalid = form.querySelector(':invalid');
    if (firstInvalid) {
      firstInvalid.focus();
      return;
    }

    const data = new FormData(form);
